<!--
  升级路线主页面：承载路线列表、创建向导、分层路线图、节点检查器与出售操作。
  页面只展示真实物品产生的实际收支；计划物品预算始终独立呈现，避免口径混算。
-->
<template>
  <div class="page routes-page">
    <PageHeader :title="screenTitle" :subtitle="screenSubtitle">
      <template v-if="pageMode === 'detail'">
        <button class="secondary-button" @click="backToList">路线列表</button>
        <PrimaryButton label="新建路线" :icon="plusIcon" @click="openCreate" />
      </template>
      <PrimaryButton v-else label="新建路线" :icon="plusIcon" @click="openCreate" />
    </PageHeader>

    <AsyncState v-if="pageMode === 'list'" :loading="loading" :error="error" :empty="routes.length === 0" empty-title="还没有升级路线" empty-text="创建一条路线，从第一件物品开始记录升级历程。" @retry="loadRoutes">
      <template #empty-action><PrimaryButton label="新建路线" :icon="plusIcon" @click="openCreate" /></template>
      <section class="routes-overview" aria-label="路线列表">
        <article v-for="route in routes" :key="route.id" class="card route-overview-card" tabindex="0" @click="openRoute(route.id)" @keyup.enter="openRoute(route.id)">
          <h2>{{ route.name }}</h2><p>{{ route.remark || '围绕真实物品，记录每一次更换与出售。' }}</p>
          <div class="route-thumb-line" aria-hidden="true"><template v-for="(image, index) in routeCoverImages(route)" :key="`${route.id}-${index}`"><i v-if="index" /><img :src="image" alt="" /></template><span v-if="!routeCoverImages(route).length" class="route-cover-empty">物品</span></div>
          <div class="route-overview-metrics"><div><span>总支出</span><strong>{{ money(routeActual(route).totalSpend) }}</strong></div><div><span>净投入</span><strong>{{ money(routeActual(route).netInvestment) }}</strong></div></div>
          <footer><span>{{ routeActual(route).assetCount || 0 }} 件物品 · {{ routePeriod(route) }}</span><span>查看路线 →</span></footer>
        </article>
      </section>
    </AsyncState>

    <template v-else>
      <div class="detail-route-bar"><div class="route-picker"><span>当前路线</span><el-select v-model="selectedRouteId" class="dl-select" @change="loadGraph"><el-option v-for="route in routes" :key="route.id" :label="route.name" :value="route.id" /></el-select></div><div class="route-bar-actions"><button class="text-button" @click="openEditRoute(currentRoute)">编辑路线</button><button class="text-button danger" @click="confirmRemoveRoute">删除路线</button></div></div>

      <AsyncState :loading="graphLoading" :error="graphError" :empty="false" @retry="loadGraph">
        <template v-if="graph">
          <section class="dark-card route-finance" aria-label="路线真实收支汇总">
            <div class="finance-lead"><span>实际净投入</span><strong>{{ money(actualSummary.netInvestment) }}</strong><small>{{ actualSummary.assetCount }} 件真实物品 · 数据随物品记录实时更新</small></div>
            <div class="finance-item"><span>累计总支出</span><b>{{ money(actualSummary.totalSpend) }}</b><small>主商品 {{ money(actualSummary.primarySpend) }}</small></div>
            <div class="finance-item income"><span>出售净收入</span><b>{{ money(actualSummary.totalIncome) }}</b><small>仅主商品出售计入补款</small></div>
            <div class="finance-item"><span>日均成本</span><b>{{ money(actualSummary.dailyCost) }}</b><small>{{ routePeriod(currentRoute) }}</small></div>
          </section>

          <section class="route-tools"><div class="segment-switch" role="tablist"><button :class="{active: detailView === 'graph'}" role="tab" :aria-selected="detailView === 'graph'" @click="detailView = 'graph'">路线图</button><button :class="{active: detailView === 'table'}" role="tab" :aria-selected="detailView === 'table'" @click="detailView = 'table'">路线明细</button></div><el-select v-model="nodeFilter" clearable class="filter-select" placeholder="全部状态"><el-option label="当前使用" value="使用中" /><el-option label="已出售" value="已出售" /><el-option label="心愿物品" value="WISHLIST" /><el-option label="数据异常" value="warning" /></el-select><el-select v-model="relationFilter" clearable class="filter-select" placeholder="全部关系"><el-option label="前后代" value="SEQUENCE" /><el-option label="同级" value="ALTERNATIVE" /></el-select><el-select v-model="generationFilter" clearable class="filter-select" placeholder="全部代际"><el-option v-for="(_, index) in layers" :key="index" :label="generationLabel(index + 1)" :value="index + 1" /></el-select></section>

          <section v-if="graph.warnings?.length" class="warning-strip" role="status"><strong>数据提示</strong><span v-for="warning in graph.warnings" :key="warning">{{ warning }}</span></section>

          <section v-if="detailView === 'graph'" class="route-workspace">
            <div class="route-canvas card">
              <div class="canvas-heading"><div><h2>物品升级路线</h2><p>选择物品后可添加上级、同级或下级；同级备用不参与主线价差计算。</p></div><button class="text-button" @click="selectedNodeId = undefined">取消选择</button></div>
              <div v-if="!visibleNodes.length" class="canvas-empty"><strong>路线还没有物品</strong><p>先新建一件物品，或从已有物品与心愿单中选择。</p><PrimaryButton label="新建第一件物品" :icon="plusIcon" @click="openFirstAssetCreator" /></div>
              <div v-else class="generation-track">
                <article v-for="(layer, layerIndex) in layers" :key="layerIndex" class="generation-column">
                  <header class="generation-header"><span>{{ generationLabel(layerIndex + 1) }}</span><strong>{{ generationPeriod(layer) }}</strong></header>
                  <div class="generation-nodes"><template v-for="node in layer" :key="node.nodeId"><button v-if="visibleNodes.includes(node)" class="route-node-card" :class="nodeClasses(node)" @click="selectNode(node.nodeId)"><span class="node-status">{{ nodeStatusLabel(node) }}</span><div class="node-image"><img :src="node.coverImageUrl || generationImage(nodeGeneration(node))" :alt="nodeName(node)" /></div><div class="node-content"><strong>{{ nodeName(node) }}</strong><span>{{ node.brandName || node.targetName || '未填写品牌 / 型号' }}</span><div class="node-facts"><span>{{ formatDate(node.purchaseDate || node.periodLabel) }}</span><b>{{ money(node.primaryPurchaseAmount ?? node.purchasePrice ?? node.plannedBudget) }}</b></div><div class="node-meta"><span>已用 {{ useDaysLabel(node) }}</span><span v-if="node.mainSaleNetIncome !== undefined || node.salePrice">已售 {{ money(node.mainSaleNetIncome ?? node.salePrice) }}</span><span v-else>{{ node.nodeType === 'PLANNED' ? '计划中' : '未出售' }}</span></div></div></button><div v-for="link in linksTo(node)" :key="link.linkId" class="relation-chip" :class="{ alternative: relationType(link) === 'ALTERNATIVE' }"><span>{{ relationType(link) === 'ALTERNATIVE' ? '同级对比' : gapLabel(link) }}</span><b v-if="relationType(link) === 'SEQUENCE'">{{ priceDeltaLabel(link) }}</b><small v-if="relationType(link) === 'SEQUENCE'">{{ netOutflowLabel(link) }}</small></div></template></div>
                </article>
              </div>
            </div>
            <aside class="node-inspector card" :class="{empty: !selectedNode}"><template v-if="selectedNode"><div class="inspector-heading"><span>物品详情</span><button class="icon-button" aria-label="关闭物品详情" @click="selectedNodeId = undefined">×</button></div><button class="inspector-image-button" :aria-label="`放大查看${nodeName(selectedNode)}图片`" @click="openImagePreview(selectedNode.coverImageUrl || generationImage(nodeGeneration(selectedNode)))"><img class="inspector-image" :src="selectedNode.coverImageUrl || generationImage(nodeGeneration(selectedNode))" :alt="nodeName(selectedNode)" /><span>点击放大</span></button><button class="inspector-name-link" :disabled="!selectedNode.assetId" @click="openAssetDetail(selectedNode)">{{ nodeName(selectedNode) }} <span v-if="selectedNode.assetId">查看更多 ↗</span></button><p>{{ selectedNode.brandName || selectedNode.model || '未填写品牌 / 型号' }}</p><div class="inspector-status"><span class="tag" :class="{lime: selectedNode.assetId === currentRoute?.mainAssetId}">{{ selectedNode.assetId === currentRoute?.mainAssetId ? '当前主物品' : nodeStatusLabel(selectedNode) }}</span><span>{{ selectedNode.nodeType === 'WISHLIST' ? '心愿物品' : selectedNode.mainline ? '同级主物品' : '备用物品' }}</span></div><dl><div><dt>购买时间</dt><dd>{{ formatDate(selectedNode.purchaseDate) }}</dd></div><div><dt>主商品金额</dt><dd>{{ money(selectedNode.primaryPurchaseAmount ?? selectedNode.purchasePrice ?? selectedNode.plannedBudget) }}</dd></div><div><dt>总投入</dt><dd>{{ money(selectedNode.totalInvest ?? selectedNode.plannedBudget) }}</dd></div><div><dt>使用时间</dt><dd>{{ useDaysLabel(selectedNode) }}</dd></div><div v-if="selectedNode.mainSaleDate" class="wide"><dt>出售记录</dt><dd>{{ formatDate(selectedNode.mainSaleDate) }} · 净收入 {{ money(selectedNode.mainSaleNetIncome) }}</dd></div></dl><div v-if="selectedNode.dataWarnings?.length" class="node-warnings"><span v-for="warning in selectedNode.dataWarnings" :key="warning">{{ warning }}</span></div><div class="inspector-actions"><PrimaryButton label="添加上级" @click="openAddNode(selectedNode, 'BEFORE')" /><PrimaryButton label="添加同级" @click="openAddNode(selectedNode, 'ALTERNATIVE')" /><PrimaryButton label="添加下级" @click="openAddNode(selectedNode, 'AFTER')" /><button v-if="selectedNode.assetId && selectedNode.assetId !== currentRoute?.mainAssetId" class="secondary-button" @click="setRouteMainAsset(selectedNode)">设为当前主物品</button><button v-if="!selectedNode.mainline" class="secondary-button" @click="setNodeMainline(selectedNode)">设为同级主物品</button><button class="secondary-button" @click="openEditNode(selectedNode)">编辑节点</button><button v-if="selectedNode.assetId && !isSold(selectedNode)" class="secondary-button sell-button" @click="openSell(selectedNode)">记录出售</button><button class="text-button danger" @click="confirmRemoveNode(selectedNode)">从路线移除</button></div></template><template v-else><div class="inspector-empty-mark">＋</div><strong>选择一件物品</strong><p>查看主商品信息、购买与相邻代际计算结果。</p></template></aside>
          </section>

          <section v-else class="card route-table"><div class="table-scroll"><table><thead><tr><th>层级</th><th>物品</th><th>关系</th><th>购买日期</th><th>购买金额</th><th>使用天数</th><th>出售净收入</th><th>与上级间隔</th><th>购买价差</th><th>实际升级补款</th></tr></thead><tbody><tr v-for="node in visibleNodes" :key="node.nodeId" tabindex="0" @click="selectNode(node.nodeId)" @keyup.enter="selectNode(node.nodeId)"><td><span class="generation-mini">{{ generationLabel(nodeGeneration(node)) }}</span></td><td><div class="table-product"><img :src="node.coverImageUrl || generationImage(nodeGeneration(node))" alt="" /><div><strong>{{ nodeName(node) }}</strong><span>{{ nodeStatusLabel(node) }}</span></div></div></td><td>{{ nodeRelationLabel(node) }}</td><td>{{ formatDate(node.purchaseDate || node.periodLabel) }}</td><td>{{ money(node.primaryPurchaseAmount ?? node.purchasePrice ?? node.plannedBudget) }}</td><td>{{ useDaysLabel(node) }}</td><td>{{ node.mainSaleNetIncome !== undefined ? money(node.mainSaleNetIncome) : '—' }}</td><td>{{ nodeIncomingLink(node) ? gapLabel(nodeIncomingLink(node)!) : '—' }}</td><td>{{ nodeIncomingLink(node) ? priceDeltaLabel(nodeIncomingLink(node)!) : '—' }}</td><td>{{ nodeIncomingLink(node) ? netOutflowLabel(nodeIncomingLink(node)!) : '—' }}</td></tr></tbody></table></div></section>
        </template>
      </AsyncState>
    </template>

    <!-- 三步创建流程：路线信息、选择第一件物品、确认后原子创建。 -->
    <el-drawer v-model="createDrawer" :title="createStepTitle" size="min(700px, calc(100vw - 24px))" class="route-drawer" destroy-on-close @closed="resetCreate">
      <el-steps :active="createStep" simple class="create-steps"><el-step title="路线信息" /><el-step title="第一件物品" /><el-step title="确认创建" /></el-steps>
      <section v-if="createStep === 0" class="drawer-section"><p class="drawer-intro">路线的时间范围会按最早与最晚的真实购买时间自动生成。</p><el-form label-position="top" class="dl-form"><el-form-item label="路线名称" required><el-input v-model="createForm.name" placeholder="例如：主力手机升级路线" maxlength="200" show-word-limit /></el-form-item><el-form-item label="路线状态"><el-select v-model="createForm.status"><el-option label="进行中" value="ACTIVE" /><el-option label="已完成" value="COMPLETED" /><el-option label="已归档" value="ARCHIVED" /></el-select></el-form-item><el-form-item label="路线说明"><el-input v-model="createForm.remark" type="textarea" :rows="4" maxlength="2000" show-word-limit /></el-form-item></el-form></section>
      <section v-else-if="createStep === 1" class="drawer-section"><p class="drawer-intro">选择首件已有物品，或从心愿单中选择待购目标；也可直接新建物品。</p><div class="asset-picker-tools"><label class="search-box"><img :src="searchIcon" alt="" /><input v-model.trim="assetKeyword" placeholder="搜索名称、品牌或分类" /></label><button class="secondary-button" @click="openFirstAssetCreator">新建物品</button></div><div class="node-kind-switch"><button :class="{active: createSource === 'ASSET'}" @click="createSource='ASSET'">已有物品</button><button :class="{active: createSource === 'WISHLIST'}" @click="createSource='WISHLIST'">心愿单</button></div><div v-if="createSource==='ASSET'" class="asset-select-list"><button v-for="asset in filteredAssets" :key="asset.id" class="asset-select-row" :class="{selected: createForm.firstAssetId === asset.id}" @click="createForm.firstAssetId = asset.id; createForm.firstWishlistId = undefined"><img v-if="asset.coverImageUrl" :src="asset.coverImageUrl" :alt="asset.name" /><span v-else class="asset-fallback">{{ asset.name.slice(0, 2) }}</span><span><strong>{{ asset.name }}</strong><small>{{ asset.brandName || asset.categoryPath || '未分类' }} · {{ formatDate(asset.primaryPurchaseDate || asset.purchaseDate) }}</small></span><b>{{ money(asset.primaryPrice || asset.totalInvest) }}</b></button></div><div v-else class="asset-select-list"><button v-for="wish in filteredWishlists" :key="wish.id" class="asset-select-row" :class="{selected: createForm.firstWishlistId === wish.id}" @click="createForm.firstWishlistId = wish.id; createForm.firstAssetId = undefined"><img v-if="wish.imageUrl" :src="wish.imageUrl" :alt="wish.name" /><span v-else class="asset-fallback">{{ wish.name.slice(0, 2) }}</span><span><strong>{{ wish.name }}</strong><small>{{ wish.brandName || '心愿物品' }} · {{ wish.status }}</small></span><b>{{ money(wish.currentPrice || wish.expectedPrice) }}</b></button></div></section>
      <section v-else class="drawer-section"><div class="creation-confirm"><span class="confirm-kicker">即将创建</span><h2>{{ createForm.name || '未命名路线' }}</h2><p>{{ createForm.remark || '暂无说明' }}</p><div><span>首件物品</span><strong>{{ creationFirstNodeLabel }}</strong></div><div><span>时间范围</span><strong>按物品实际购买时间自动计算</strong></div><div><span>实际支出</span><strong>首件创建后按物品购买记录计算</strong></div></div></section>
      <template #footer><button v-if="createStep" class="secondary-button" @click="createStep--">上一步</button><button class="secondary-button" @click="createDrawer=false">取消</button><PrimaryButton :label="createStep === 2 ? '创建路线' : '下一步'" :loading="saving" @click="nextCreate" /></template>
    </el-drawer>

    <!-- 节点抽屉由锚点与位置驱动，关系由后端自动创建。 -->
    <el-drawer v-model="nodeDrawer" :title="nodeDrawerTitle" size="min(640px, calc(100vw - 24px))" class="route-drawer" destroy-on-close @closed="resetNodeForm">
      <section class="drawer-section"><div v-if="nodeAnchor" class="anchor-summary"><span>锚点物品</span><strong>{{ nodeName(nodeAnchor) }}</strong><small>{{ positionLabel(nodePosition) }}此物品；保存后系统会重新排序主线并计算价格。</small></div><div class="node-kind-switch"><button :class="{active: nodeForm.nodeType === 'ASSET'}" @click="nodeForm.nodeType = 'ASSET'">选择已有物品</button><button :class="{active: nodeForm.nodeType === 'WISHLIST'}" @click="nodeForm.nodeType = 'WISHLIST'">从心愿单选择</button></div><template v-if="nodeForm.nodeType === 'ASSET'"><label class="search-box"><img :src="searchIcon" alt="" /><input v-model.trim="nodeAssetKeyword" placeholder="搜索名称、品牌或分类" /></label><div class="asset-select-list compact"><button v-for="asset in nodeAvailableAssets" :key="asset.id" class="asset-select-row" :class="{selected: nodeForm.assetId === asset.id}" @click="nodeForm.assetId = asset.id; nodeForm.wishlistId = undefined"><img v-if="asset.coverImageUrl" :src="asset.coverImageUrl" :alt="asset.name" /><span v-else class="asset-fallback">{{ asset.name.slice(0, 2) }}</span><span><strong>{{ asset.name }}</strong><small>{{ formatDate(asset.primaryPurchaseDate || asset.purchaseDate) }} · {{ asset.status }}</small></span><b>{{ money(asset.primaryPrice || asset.totalInvest) }}</b></button></div></template><template v-else><label class="search-box"><img :src="searchIcon" alt="" /><input v-model.trim="nodeAssetKeyword" placeholder="搜索心愿单" /></label><div class="asset-select-list compact"><button v-for="wish in filteredWishlists" :key="wish.id" class="asset-select-row" :class="{selected: nodeForm.wishlistId === wish.id}" @click="nodeForm.wishlistId = wish.id; nodeForm.assetId = undefined"><img v-if="wish.imageUrl" :src="wish.imageUrl" :alt="wish.name" /><span v-else class="asset-fallback">{{ wish.name.slice(0, 2) }}</span><span><strong>{{ wish.name }}</strong><small>{{ wish.brandName || '心愿物品' }}</small></span><b>{{ money(wish.currentPrice || wish.expectedPrice) }}</b></button></div></template><el-form label-position="top" class="dl-form"><el-form-item label="添加说明"><el-input v-model="nodeForm.remark" type="textarea" :rows="3" placeholder="例如：影像升级、通勤备用，保存后显示在物品详情中" /></el-form-item><el-form-item v-if="nodePosition === 'ALTERNATIVE'" label="同级角色"><el-radio-group v-model="nodeForm.mainline"><el-radio :value="true">主物品（参与上下级计算）</el-radio><el-radio :value="false">备用物品（仅计入总额）</el-radio></el-radio-group></el-form-item></el-form><div v-if="relationshipPreview" class="relation-preview"><strong>{{ nodePosition === 'ALTERNATIVE' ? '同级关系预览' : '前后代关系预览' }}</strong><div><span>购买时间差</span><b>{{ relationshipPreview.days }}</b></div><div><span>购买价差</span><b>{{ relationshipPreview.price }}</b></div><div v-if="nodePosition !== 'ALTERNATIVE'"><span>实际升级补款</span><b>{{ relationshipPreview.outflow }}</b></div></div></section>
      <template #footer><button class="secondary-button" @click="nodeDrawer=false">取消</button><PrimaryButton label="保存关联物品" :loading="saving" @click="saveNode" /></template>
    </el-drawer>

    <el-drawer v-model="editRouteDrawer" title="编辑升级路线" size="min(580px, calc(100vw - 24px))" class="route-drawer" destroy-on-close><el-form label-position="top" class="dl-form drawer-section"><el-form-item label="路线名称" required><el-input v-model="editRouteForm.name" /></el-form-item><el-form-item label="路线状态"><el-select v-model="editRouteForm.status"><el-option label="进行中" value="ACTIVE" /><el-option label="已完成" value="COMPLETED" /><el-option label="已归档" value="ARCHIVED" /></el-select></el-form-item><el-form-item label="路线说明"><el-input v-model="editRouteForm.remark" type="textarea" :rows="4" /></el-form-item></el-form><template #footer><button class="secondary-button" @click="editRouteDrawer=false">取消</button><PrimaryButton label="保存修改" :loading="saving" @click="saveRouteEdit" /></template></el-drawer>

    <el-drawer v-model="editNodeDrawer" title="编辑路线物品" size="min(560px, calc(100vw - 24px))" class="route-drawer" destroy-on-close><el-form label-position="top" class="dl-form drawer-section"><el-form-item label="关联物品"><el-select v-model="editNodeForm.assetId" filterable placeholder="搜索并重新选择物品"><el-option v-for="asset in assets" :key="asset.id" :label="asset.name" :value="asset.id" /></el-select></el-form-item><el-form-item label="显示标签"><el-input v-model="editNodeForm.label" placeholder="留空则显示物品名称" /></el-form-item><el-form-item label="节点说明"><el-input v-model="editNodeForm.remark" type="textarea" :rows="5" /></el-form-item><el-form-item label="同级角色"><el-radio-group v-model="editNodeForm.mainline"><el-radio :value="true">主物品</el-radio><el-radio :value="false">备用物品</el-radio></el-radio-group></el-form-item></el-form><template #footer><button class="secondary-button" @click="editNodeDrawer=false">取消</button><PrimaryButton label="保存节点" :loading="saving" @click="saveNodeEdit" /></template></el-drawer>

    <el-dialog v-model="sellDialog" title="记录主商品出售" width="560px"><p class="sale-dialog-note">出售后会自动更新该物品的使用时间、路线收入及相邻升级补款；配件出售不在此处记录。</p><el-form label-position="top" class="dialog-form"><div class="dialog-grid"><el-form-item label="出售日期" required><el-date-picker v-model="sellForm.saleDate" type="date" value-format="YYYY-MM-DD" /></el-form-item><el-form-item label="成交金额" required><el-input-number v-model="sellForm.salePrice" :min="0" :precision="2" /></el-form-item><el-form-item label="手续费"><el-input-number v-model="sellForm.fee" :min="0" :precision="2" /></el-form-item><el-form-item label="运费及其他成本"><el-input-number v-model="sellForm.shippingCost" :min="0" :precision="2" /></el-form-item></div><el-form-item label="备注"><el-input v-model="sellForm.notes" type="textarea" /></el-form-item></el-form><template #footer><button class="secondary-button" @click="sellDialog=false">取消</button><PrimaryButton label="保存出售记录" :loading="saving" @click="saveSale" /></template></el-dialog>
    <el-dialog v-model="previewOpen" title="物品图片" width="min(760px, calc(100vw - 32px))" class="image-preview-dialog"><img v-if="previewImage" class="image-preview" :src="previewImage" alt="物品放大预览" /></el-dialog>
  </div>
</template>

<script setup lang="ts">
/**
 * 升级路线交互逻辑。
 * 后端新契约已返回完整图与计算结果；本文件同时为旧数据的字段缺失做展示层降级，
 * 不在前端伪造真实收支，也不会把计划预算计入实际金额。
 */
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { createRoute, createRouteNode, deleteRoute, deleteRouteNode, fetchRouteGraph, fetchRoutes, updateRoute, updateRouteNode, type NodePayload, type RoutePayload } from '@/api/upgrade'
import { fetchAssets, sellAsset, type SellPayload } from '@/api/assets'
import { fetchWishlist } from '@/api/wishlist'
import type { AssetSummary, UpgradeActualSummary, UpgradeGraphLink, UpgradeGraphNode, UpgradeRelationType, UpgradeRouteGraph, UpgradeRouteItem, UpgradeRouteType, WishlistItem } from '@/types'
import { useWorkspaceStore } from '@/stores/workspace'
import PageHeader from '@/components/PageHeader.vue'
import PrimaryButton from '@/components/PrimaryButton.vue'
import AsyncState from '@/components/AsyncState.vue'
import plusIcon from '@/assets/icons/plus.svg'
import searchIcon from '@/assets/icons/search.svg'

type NodePosition = 'BEFORE' | 'ALTERNATIVE' | 'AFTER'
const routes = ref<UpgradeRouteItem[]>([])
const assets = ref<AssetSummary[]>([])
const wishlists = ref<WishlistItem[]>([])
const router = useRouter()
const workspace = useWorkspaceStore()
const graph = ref<UpgradeRouteGraph>()
const selectedRouteId = ref<number>()
const selectedNodeId = ref<number>()
const loading = ref(true)
const graphLoading = ref(false)
const saving = ref(false)
const error = ref('')
const graphError = ref('')
const pageMode = ref<'list' | 'detail'>('list')
const detailView = ref<'graph' | 'table'>('graph')
const nodeFilter = ref('')
const relationFilter = ref<UpgradeRelationType | ''>('')
const generationFilter = ref<number>()
const createDrawer = ref(false)
const createStep = ref(0)
const createSource = ref<'ASSET' | 'WISHLIST'>('ASSET')
const assetKeyword = ref('')
const nodeDrawer = ref(false)
const nodeAnchor = ref<UpgradeGraphNode>()
const nodePosition = ref<NodePosition>('AFTER')
const nodeAssetKeyword = ref('')
const editRouteDrawer = ref(false)
const editNodeDrawer = ref(false)
const editingRouteId = ref<number>()
const editingNodeId = ref<number>()
const sellDialog = ref(false)
const sellingNode = ref<UpgradeGraphNode>()
const previewOpen = ref(false)
const previewImage = ref('')

const createForm = reactive({ name: '', remark: '', status: 'ACTIVE' as const, firstAssetId: undefined as number | undefined, firstWishlistId: undefined as number | undefined })
const nodeForm = reactive<NodePayload>({ nodeType: 'ASSET', assetId: undefined, wishlistId: undefined, remark: '', alternativePurpose: '', mainline: true })
const editRouteForm = reactive<RoutePayload>({ name: '', remark: '', routeType: 'ACTUAL', status: 'ACTIVE' })
const editNodeForm = reactive({ assetId: undefined as number | undefined, label: '', remark: '', mainline: true })
const sellForm = reactive({ saleDate: new Date().toISOString().slice(0, 10), salePrice: 0, fee: 0, shippingCost: 0, notes: '' })

const currentRoute = computed(() => routes.value.find(route => route.id === selectedRouteId.value))
const screenTitle = computed(() => pageMode.value === 'list' ? '升级路线' : currentRoute.value?.name || '升级路线')
const screenSubtitle = computed(() => pageMode.value === 'list' ? '' : '主线按购买时间自动排序；备用物品只计入路线总额。')
const selectedNode = computed(() => graph.value?.nodes.find(node => node.nodeId === selectedNodeId.value))
const actualSummary = computed<UpgradeActualSummary>(() => graph.value?.actualSummary || routeActual(currentRoute.value) || { assetCount: graph.value?.nodes.filter(node => node.nodeType !== 'PLANNED').length || 0, totalSpend: 0, primarySpend: 0, extraSpend: 0, totalIncome: 0, netInvestment: 0 })
const visibleNodes = computed(() => (graph.value?.nodes || []).filter(node => {
  const statusMatched = !nodeFilter.value || (nodeFilter.value === 'warning' ? Boolean(node.dataWarnings?.length) : nodeFilter.value === 'WISHLIST' ? node.nodeType === 'WISHLIST' : nodeStatusLabel(node) === nodeFilter.value)
  const generationMatched = !generationFilter.value || nodeGeneration(node) === generationFilter.value
  const relationMatched = !relationFilter.value || linksTo(node).some(link => relationType(link) === relationFilter.value) || (relationFilter.value === 'SEQUENCE' && !linksTo(node).length)
  return statusMatched && generationMatched && relationMatched
}))
const layers = computed(() => {
  const allNodes = graph.value?.nodes || []
  const maxGeneration = Math.max(1, ...allNodes.map(nodeGeneration))
  return Array.from({ length: maxGeneration }, (_, index) => allNodes.filter(node => nodeGeneration(node) === index + 1))
})
const filteredAssets = computed(() => filterAssets(assetKeyword.value, false))
const nodeAvailableAssets = computed(() => filterAssets(nodeAssetKeyword.value, true))
const filteredWishlists = computed(() => filterWishlists(nodeAssetKeyword.value || assetKeyword.value))
const selectedNewAsset = computed(() => assets.value.find(asset => asset.id === nodeForm.assetId))
const creationFirstNodeLabel = computed(() => assets.value.find(asset => asset.id === createForm.firstAssetId)?.name || wishlists.value.find(wish => wish.id === createForm.firstWishlistId)?.name || '未选择物品')
const createStepTitle = computed(() => ['新建升级路线', '选择第一件物品', '确认创建'][createStep.value])
const nodeDrawerTitle = computed(() => nodeAnchor.value ? `添加${positionLabel(nodePosition.value)}物品` : '添加第一件物品')
const relationshipPreview = computed(() => {
  if (!nodeAnchor.value) return undefined
  const anchorDate = nodeAnchor.value.purchaseDate
  const childDate = selectedNewAsset.value?.primaryPurchaseDate || selectedNewAsset.value?.purchaseDate || nodeForm.periodLabel
  const anchorPrice = Number(nodeAnchor.value.primaryPurchaseAmount ?? nodeAnchor.value.purchasePrice ?? 0)
  const childPrice = Number(selectedNewAsset.value?.primaryPrice ?? selectedNewAsset.value?.totalInvest ?? nodeForm.plannedBudget ?? 0)
  const days = anchorDate && childDate ? `${daysBetween(anchorDate, childDate)} 天` : '待补充购买日期'
  const price = anchorPrice || childPrice ? signedMoney(childPrice - anchorPrice) : '待补充金额'
  const saleIncome = nodeAnchor.value.mainSaleNetIncome
  return { days, price, outflow: saleIncome === undefined ? '出售后计算' : money(childPrice - saleIncome) }
})

function money(value?: number) { return `¥${Number(value || 0).toLocaleString('zh-CN', { maximumFractionDigits: 2 })}` }
function signedMoney(value?: number | null) { if (value === null || value === undefined) return '待计算'; return `${value > 0 ? '+' : value < 0 ? '−' : ''}${money(Math.abs(value))}` }
function formatDate(value?: string) { if (!value) return '数据未记录'; const matched = value.match(/^(\d{4})-(\d{2})/); return matched ? `${matched[1]} 年 ${matched[2]} 月` : value }
function daysBetween(start: string, end: string) { return Math.round((new Date(end).getTime() - new Date(start).getTime()) / 86400000) }
function routeTypeLabel(type?: UpgradeRouteType) { return ({ ACTUAL: '实际履历', PLAN: '未来规划', MIXED: '实际 + 规划' }[type || 'ACTUAL']) }
function nodeName(node: UpgradeGraphNode) { return node.label || node.name || node.title || node.targetName || '未命名物品' }
function nodeGeneration(node: UpgradeGraphNode) { return Math.max(1, Number(node.level || 1)) }
function generationLabel(index: number) { return `第 ${index} 代` }
/** 无封面时使用轻量文字占位，路线卡片不再依赖固定示例商品图。 */
function generationImage(index: number) { return `data:image/svg+xml,${encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="260" height="180"><rect width="100%" height="100%" fill="#eaffbf"/><text x="50%" y="53%" dominant-baseline="middle" text-anchor="middle" fill="#4d6421" font-size="28">第 ${index} 代</text></svg>`)}` }
function generationPeriod(layer: UpgradeGraphNode[]) { const dates = layer.map(node => node.purchaseDate || node.periodLabel).filter(Boolean).sort(); return dates[0] ? formatDate(dates[0]) : '待定年月' }
function nodeStatusLabel(node: UpgradeGraphNode) { if (node.nodeType === 'WISHLIST' || node.nodeType === 'PLANNED') return '心愿中'; if (isSold(node)) return '已出售'; return node.assetStatus || node.status || '数据待补充' }
function useDaysLabel(node: UpgradeGraphNode) { return node.useDays === undefined || node.useDays === null ? '待计算' : `${node.useDays} 天` }
function isSold(node: UpgradeGraphNode) { return Boolean(node.sold || node.assetStatus === '已出售' || node.mainSaleDate || node.mainSaleNetIncome !== undefined) }
function relationType(link: UpgradeGraphLink): UpgradeRelationType { return link.relationType || 'SEQUENCE' }
function linksTo(node: UpgradeGraphNode) { return (graph.value?.links || []).filter(link => link.toNodeId === node.nodeId) }
function nodeIncomingLink(node: UpgradeGraphNode) { return linksTo(node)[0] }
function nodeRelationLabel(node: UpgradeGraphNode) { const link = nodeIncomingLink(node); return link ? relationType(link) === 'ALTERNATIVE' ? '同级对比' : '前后代' : '起点物品' }
function gapLabel(link: UpgradeGraphLink) { return link.purchaseGapDays === null || link.purchaseGapDays === undefined ? '购买时间待补充' : `${link.purchaseGapDays} 天后` }
function priceDeltaLabel(link: UpgradeGraphLink) { return link.purchasePriceDelta === null || link.purchasePriceDelta === undefined ? '购入价待补充' : `购入价 ${signedMoney(link.purchasePriceDelta)}` }
function netOutflowLabel(link: UpgradeGraphLink) { return link.replacementNetOutflow === null || link.replacementNetOutflow === undefined ? '出售后计算' : `实际补款 ${money(link.replacementNetOutflow)}` }
function nodeClasses(node: UpgradeGraphNode) { return { selected: node.nodeId === selectedNodeId.value, sold: isSold(node), planned: node.nodeType === 'PLANNED' || node.status === 'PLANNED', active: node.assetStatus === '使用中', mainProduct: node.assetId === currentRoute.value?.mainAssetId, warning: Boolean(node.dataWarnings?.length) } }
function positionLabel(position: NodePosition) { return ({ BEFORE: '上级', ALTERNATIVE: '同级', AFTER: '下级' }[position]) }
function routeActual(route?: UpgradeRouteItem): UpgradeActualSummary { return route?.actualSummary || { assetCount: 0, totalSpend: 0, primarySpend: 0, extraSpend: 0, totalIncome: 0, netInvestment: 0 } }
function filterAssets(keyword: string, excludeCurrent: boolean) { const used = new Set((graph.value?.nodes || []).map(node => node.assetId).filter((id): id is number => Boolean(id))); const needle = keyword.trim().toLowerCase(); return assets.value.filter(asset => (!excludeCurrent || !used.has(asset.id)) && (!needle || `${asset.name} ${asset.brandName || ''} ${asset.categoryPath || ''}`.toLowerCase().includes(needle))).slice(0, 20) }
function filterWishlists(keyword: string) { const used = new Set((graph.value?.nodes || []).map(node => node.wishlistId).filter((id): id is number => Boolean(id))); const needle = keyword.trim().toLowerCase(); return wishlists.value.filter(item => item.status !== '已购买' && !used.has(item.id) && (!needle || `${item.name} ${item.brandName || ''} ${item.categoryName || ''}`.toLowerCase().includes(needle))).slice(0, 20) }
function routeCoverImages(route: UpgradeRouteItem) { return (route.coverImageUrls || []).slice(0, 3) }
function routePeriod(route?: UpgradeRouteItem) { if (!route?.periodStart) return '购买时间待补充'; const start = formatDate(route.periodStart); const end = route.periodEnd && route.periodEnd !== route.periodStart ? formatDate(route.periodEnd) : ''; return end ? `${start} — ${end}` : start }

async function loadRoutes() {
  loading.value = true; error.value = ''
  try { routes.value = await fetchRoutes() } catch (e) { error.value = (e as Error).message } finally { loading.value = false }
}
async function loadAssets(keyword = '') { try { assets.value = await fetchAssets({ keyword }) } catch { assets.value = [] } }
async function loadWishlists() { try { wishlists.value = await fetchWishlist() } catch { wishlists.value = [] } }
async function loadGraph() {
  if (!selectedRouteId.value) return
  graphLoading.value = true; graphError.value = ''
  try { graph.value = await fetchRouteGraph(selectedRouteId.value); selectedNodeId.value = undefined } catch (e) { graphError.value = (e as Error).message } finally { graphLoading.value = false }
}
async function openRoute(id: number) { selectedRouteId.value = id; pageMode.value = 'detail'; await loadGraph() }
function backToList() { pageMode.value = 'list'; selectedNodeId.value = undefined }
function selectNode(id: number) { selectedNodeId.value = id }
function openCreate() { resetCreate(); createDrawer.value = true }
function resetCreate() { createStep.value = 0; createSource.value = 'ASSET'; assetKeyword.value = ''; Object.assign(createForm, { name: '', remark: '', status: 'ACTIVE', firstAssetId: undefined, firstWishlistId: undefined }) }
async function nextCreate() {
  if (createStep.value === 0) { if (!createForm.name.trim()) return ElMessage.warning('请输入路线名称'); createStep.value++; return }
  if (createStep.value === 1) { if (!createForm.firstAssetId && !createForm.firstWishlistId) return ElMessage.warning('请选择第一件物品或心愿物品'); createStep.value++; return }
  const payload: RoutePayload = { name: createForm.name.trim(), remark: createForm.remark || undefined, routeType: 'ACTUAL', status: createForm.status, firstNode: createForm.firstWishlistId ? { nodeType: 'WISHLIST', wishlistId: createForm.firstWishlistId } : { nodeType: 'ASSET', assetId: createForm.firstAssetId } }
  saving.value = true
  try { const result = await createRoute(payload); const id = typeof result === 'number' ? result : result.routeId; await loadRoutes(); selectedRouteId.value = id; graph.value = typeof result === 'number' ? undefined : result; pageMode.value = 'detail'; createDrawer.value = false; if (!graph.value) await loadGraph(); ElMessage.success('升级路线已创建') } catch (e) { ElMessage.error((e as Error).message) } finally { saving.value = false }
}
function openAddNode(anchor: UpgradeGraphNode | undefined, position: NodePosition) { if (!selectedRouteId.value && anchor) return; resetNodeForm(); nodeAnchor.value = anchor; nodePosition.value = position; nodeDrawer.value = true }
function resetNodeForm() { nodeAssetKeyword.value = ''; Object.assign(nodeForm, { nodeType: 'ASSET', assetId: undefined, wishlistId: undefined, remark: '', alternativePurpose: '', mainline: true }) }
async function saveNode() {
  if (!selectedRouteId.value) return
  if (nodeForm.nodeType === 'ASSET' && !nodeForm.assetId) return ElMessage.warning('请选择一件已有物品')
  if (nodeForm.nodeType === 'WISHLIST' && !nodeForm.wishlistId) return ElMessage.warning('请选择一件心愿物品')
  const payload: NodePayload = { ...nodeForm, anchorNodeId: nodeAnchor.value?.nodeId, position: nodeAnchor.value ? nodePosition.value : 'AFTER', mainline: nodePosition.value === 'ALTERNATIVE' ? Boolean(nodeForm.mainline) : true }
  saving.value = true
  try { await createRouteNode(selectedRouteId.value, payload); nodeDrawer.value = false; await loadGraph(); ElMessage.success('关联物品已添加') } catch (e) { ElMessage.error((e as Error).message) } finally { saving.value = false }
}
function openEditRoute(route?: UpgradeRouteItem) { const target = route || currentRoute.value; if (!target) return; editingRouteId.value = target.id; Object.assign(editRouteForm, { name: target.name, remark: target.remark || '', routeType: 'ACTUAL', status: target.status || 'ACTIVE', mainAssetId: target.mainAssetId || undefined }); editRouteDrawer.value = true }
async function saveRouteEdit() { if (!editingRouteId.value || !editRouteForm.name.trim()) return ElMessage.warning('请输入路线名称'); saving.value = true; try { await updateRoute(editingRouteId.value, { ...editRouteForm, name: editRouteForm.name.trim() }); editRouteDrawer.value = false; await loadRoutes(); await loadGraph(); ElMessage.success('路线已更新') } catch (e) { ElMessage.error((e as Error).message) } finally { saving.value = false } }
function openEditNode(node: UpgradeGraphNode) { editingNodeId.value = node.nodeId; Object.assign(editNodeForm, { assetId: node.assetId, label: node.label || '', remark: node.remark || '', mainline: Boolean(node.mainline) }); editNodeDrawer.value = true }
async function saveNodeEdit() { if (!selectedRouteId.value || !editingNodeId.value || !editNodeForm.assetId) return ElMessage.warning('请选择关联物品'); saving.value = true; try { await updateRouteNode(selectedRouteId.value, editingNodeId.value, { assetId: editNodeForm.assetId, nodeType: 'ASSET', label: editNodeForm.label.trim() || undefined, remark: editNodeForm.remark.trim() || undefined, mainline: editNodeForm.mainline }); editNodeDrawer.value = false; await loadGraph(); ElMessage.success('节点已更新') } catch (e) { ElMessage.error((e as Error).message) } finally { saving.value = false } }
function openFirstAssetCreator() { workspace.openNewAsset(); ElMessage.info('保存物品后会自动刷新此处列表，再选择它作为首件物品。') }
function openAssetDetail(node: UpgradeGraphNode) { if (node.assetId) router.push(`/assets/${node.assetId}`) }
/** 弹窗状态与图片地址分离，防止地址字符串被 Element Plus 误判为“始终打开”。 */
function openImagePreview(imageUrl: string) { previewImage.value = imageUrl; previewOpen.value = true }
async function setRouteMainAsset(node: UpgradeGraphNode) { if (!selectedRouteId.value || !node.assetId || !currentRoute.value) return; saving.value = true; try { await updateRoute(selectedRouteId.value, { name: currentRoute.value.name, remark: currentRoute.value.remark || undefined, routeType: 'ACTUAL', status: currentRoute.value.status || 'ACTIVE', mainAssetId: node.assetId }); await loadRoutes(); await loadGraph(); ElMessage.success('已设为当前主物品') } catch (e) { ElMessage.error((e as Error).message) } finally { saving.value = false } }
async function setNodeMainline(node: UpgradeGraphNode) { if (!selectedRouteId.value || !node.assetId) return; saving.value = true; try { await updateRouteNode(selectedRouteId.value, node.nodeId, { assetId: node.assetId, nodeType: 'ASSET', label: node.label || undefined, remark: node.remark || undefined, mainline: true }); await loadGraph(); ElMessage.success('已设为同级主物品并重新计算主线') } catch (e) { ElMessage.error((e as Error).message) } finally { saving.value = false } }
async function confirmRemoveRoute() { if (!selectedRouteId.value) return; try { await ElMessageBox.confirm('删除路线会移除路线节点与关系，但不会删除物品中心中的物品和出售记录。', '删除升级路线', { confirmButtonText: '删除路线', cancelButtonText: '取消', type: 'warning' }); await deleteRoute(selectedRouteId.value); await loadRoutes(); graph.value = undefined; selectedRouteId.value = undefined; pageMode.value = 'list'; ElMessage.success('路线已删除') } catch (e) { if (e !== 'cancel' && e !== 'close') ElMessage.error((e as Error).message) } }
async function confirmRemoveNode(node: UpgradeGraphNode) { if (!selectedRouteId.value) return; try { await ElMessageBox.confirm('仅从这条升级路线移除该节点。物品中心中的物品和出售记录会被保留；若存在后代，后端会要求先处理其关系。', '移除路线节点', { confirmButtonText: '移除节点', cancelButtonText: '取消', type: 'warning' }); await deleteRouteNode(selectedRouteId.value, node.nodeId); selectedNodeId.value = undefined; await loadGraph(); ElMessage.success('节点已移除') } catch (e) { if (e !== 'cancel' && e !== 'close') ElMessage.error((e as Error).message) } }
function openSell(node: UpgradeGraphNode) { sellingNode.value = node; Object.assign(sellForm, { saleDate: new Date().toISOString().slice(0, 10), salePrice: 0, fee: 0, shippingCost: 0, notes: '' }); sellDialog.value = true }
async function saveSale() { if (!sellingNode.value?.assetId) return; if (!sellForm.salePrice && sellForm.salePrice !== 0) return ElMessage.warning('请输入成交金额'); const payload: SellPayload = { saleScope: 'ASSET', saleDate: sellForm.saleDate, salePrice: sellForm.salePrice, fee: sellForm.fee, shippingCost: sellForm.shippingCost, otherCost: 0, notes: sellForm.notes || undefined }; saving.value = true; try { await sellAsset(sellingNode.value.assetId, payload); sellDialog.value = false; await loadGraph(); ElMessage.success('出售记录已保存，路线计算已更新') } catch (e) { ElMessage.error((e as Error).message) } finally { saving.value = false } }

let searchTimer: ReturnType<typeof setTimeout> | undefined
watch([assetKeyword, nodeAssetKeyword], ([assetKeywordValue, nodeKeywordValue]) => { clearTimeout(searchTimer); searchTimer = setTimeout(() => loadAssets(nodeDrawer.value ? nodeKeywordValue : assetKeywordValue), 180) })
watch(() => workspace.refreshKey, async () => { await loadAssets(assetKeyword.value); await loadWishlists() })
onMounted(async () => { await Promise.all([loadRoutes(), loadAssets(), loadWishlists()]) })
</script>

